// src/pages/DoctorDashboard.jsx
import React from "react";
import "./DoctorDashboard.css";
import { useNavigate } from "react-router-dom";

const DoctorDashboard = () => {
  const navigate = useNavigate();
  const doctorName = localStorage.getItem("name") || "Doctor";

  const handleLogout = () => {
    localStorage.clear();
    navigate("/login");
  };

  return (
    <div className="doctor-dashboard">
      <aside className="sidebar">
        <div className="logo">MediVault</div>
        <nav className="nav-links">
          <a href="#" className="active">Dashboard</a>
          <a href="#">Appointments</a>
          <a href="#">Patient Records</a>
          <a href="#">Upload Report</a>
          <a href="#">Shared Reports</a>
          <a href="#">Settings</a>
          <button className="logout-btn" onClick={handleLogout}>Logout</button>
        </nav>
      </aside>

      <main className="main-content">
        <header className="dashboard-header">
          <h2>Welcome, Dr. {doctorName}</h2>
          <p>Your personalized dashboard overview</p>
        </header>

        <section className="stats-cards">
          <div className="card">
            <h3>Today's Appointments</h3>
            <p>5</p>
          </div>
          <div className="card">
            <h3>Total Patients</h3>
            <p>124</p>
          </div>
          <div className="card">
            <h3>Reports Uploaded</h3>
            <p>87</p>
          </div>
        </section>

        <section className="actions">
          <button className="upload-btn">+ Upload New Report</button>
        </section>
      </main>
    </div>
  );
};

export default DoctorDashboard;
